// === Tab: mySketch ===
let canvasSize = { w: 0, h: 0 }
let lastTime = 0
let particles = []
let baseVel = 0.2
let constVel = 0
let maxDist = 50
let duration = 3000
let maxSpeed = 8

class Particle {
  constructor () {
    this.pos = createVector(0, 0)
    this.vel = createVector(0, 0)
    this.reset()
    // this.vel = createVector(random(-baseVel, baseVel), random(-baseVel, baseVel))
    this.gravity = createVector(0, 0.002)
    this.acc = createVector(random(-0.2, 0.2), random(-0.2, 0.2))
    // this.startTime = -duration - 1
    this.attractor = createVector(0, 0)
  }

  update (x, y) {
    this.prev = this.pos.copy()
    const pos = this.pos
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && dist(pos.x, pos.y, x, y) < maxDist) {
      this.startTime = millis()
    }

    let currTime = millis()
    let timeElapsed = currTime - this.startTime
    if (100 < timeElapsed && timeElapsed < duration) {

      if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
        this.attractor.set(x, y)
        this.attractor.sub(this.pos)
        this.attractor.div(5)

        this.acc.add(this.attractor)
        this.acc.div(500)
      }

      this.acc.add(this.gravity)
      this.vel.add(this.acc)
      this.vel.limit(maxSpeed)
    } else {
      this.vel.limit(constVel)
    }

    this.pos.add(this.vel)
  }

  draw () {
    const prev = this.prev
    const curr = this.pos
    line(prev.x, prev.y, curr.x, curr.y)
  }

  isOutOfView () {
    const { w, h } = canvasSize
    var pos = this.pos
    return pos.x < 0 || pos.x >= w || pos.y < 0 || pos.y >= h
  }

  reset () {
    const { w, h } = canvasSize
    this.pos.set(random(0, w - 1), random(0, h - 1))
    this.startTime = -duration - 1
    this.vel.set(random(-baseVel, baseVel), random(-baseVel, baseVel))
  }
}

function setup () {
  canvasSize.w = windowWidth - 0
  canvasSize.h = windowHeight - 0
  const { w, h } = canvasSize

  lastTime = millis()
  constVel = sqrt(baseVel * baseVel * 2)

  createCanvas(w, h)
  background(0)

  for (let i = 0; i < 2000; i++) {
    particles.push(new Particle())
  }
}

function draw () {
  colorMode(RGB)
  background(0, 16)

  strokeWeight(2)
  stroke(15, 238, 241, 255)

  particles.forEach(p => {
    p.update((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
    p.draw()
    if (p.isOutOfView()) {
      p.reset()
    }
  })
}

